\title{User Preference-aware Fake News Detection}








\author{Yingtong Dou$^{1}$, Kai Shu$^{2}$, Congying Xia$^{1}$, Philip S. Yu$^{1}$, Lichao Sun$^{3}$}
\affiliation{
